manager_roles = {"System Manager", "URY Manager"}
cashier_max_discount = 10

user_roles = set(frappe.get_all(
    "Has Role",
    filters={"parent": frappe.session.user, "parenttype": "User"},
    pluck="role",
))
is_manager = frappe.session.user == "Administrator" or bool(manager_roles & user_roles)
is_cashier_only = not is_manager and "URY Cashier" in user_roles

if is_cashier_only and doc.get("additional_discount_percentage"):
    requested = float(doc.additional_discount_percentage or 0)

    if requested > cashier_max_discount:
        frappe.throw(
            f"Cashier can only apply up to {cashier_max_discount}% discount. Ask a Manager for more."
        )

    if doc.get("invoice_printed") and not doc.is_new():
        previous_discount = frappe.db.get_value(
            "POS Invoice", doc.name, "additional_discount_percentage"
        )
        if float(previous_discount or 0) != requested:
            frappe.throw(
                "Discount cannot be changed after the bill has been printed. Ask a Manager to adjust it."
            )
